def svg(name: str, size: int = 16, color: str = "currentColor") -> str:
    """返回 Material Design Icon 的内联 SVG 字符串。

    name  : _MDI 中的键名（movie/tv/anime/star/...）
    size  : 像素边长（SVG 会同时设置 width/height 与 viewBox 0 0 24 24）
    color : fill 颜色，默认 "currentColor" 以继承父元素文字颜色
    """
    body = _MDI.get(name, _MDI["apps"])
    return (f'<svg viewBox="0 0 24 24" width="{size}" height="{size}" '
            f'fill="{color}" style="vertical-align:middle">{body}</svg>')
